scenes.code:
* { box-sizing: border-box; }

body {
     margin: 0;
     padding: 32px 16px;
     font-family: Georgia, "Times New Roman", serif;
     background: #ffffff;
     display: flex;

    justify-content: center;
}

.bai-viet {
    width: min(800px, 100%);
}

.bai-viet h1 {
    margin: 0 0 22px;
    text-align: center;
    color: #C2185B;
    font-size: 26px;
}

.bo-cuc-2-cot {
    display: grid;
    grid-template-columns: 220px 1fr;
    gap: 24px;
    align-items: start;
}

.bo-cuc-2-cot img {
    width: 100%;
    border-radius: 8px;
    display: block;
}

.nhan-muc {
    background: #FFC0CB;
    font-size: 16px;
    font-weight: 700;
    padding: 4px 10px;
    display: inline-block;
    margin: 0 0 12px;
}

ul {
    margin: 0 0 18px;

     padding-left: 22px;
     line-height: 1.9;
}

.ds-vuong { list-style-type: square; }
.ds-tron      { list-style-type: circle; }

.ban-quyen {
     display: block;
     margin-top: 20px;
     text-align: center;
     color: #0000EE;
     text-decoration: underline;
}

@media (max-width: 600px) {
     .bo-cuc-2-cot {
         grid-template-columns: 1fr;
     }
     .bo-cuc-2-cot img {
         max-width: 220px;
         margin: 0 auto;
     }
}
